script:
test("windows that cross overlap by 30 minutes", function () {
  assert.deepEqual(code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" }), { overlaps: true, minutes: 30 });
});

test("windows that only touch at an end do not overlap", function () {
  assert.deepEqual(code.windowOverlap({ start: "09:00", end: "12:00" }, { start: "12:00", end: "13:00" }), { overlaps: false, minutes: 0 });
});

test("the same crossing pair reversed still overlaps by 30 minutes", function () {
  assert.deepEqual(code.windowOverlap({ start: "10:30", end: "12:00" }, { start: "09:00", end: "11:00" }), { overlaps: true, minutes: 30 });
});

test("one minute past a shared endpoint overlaps by 1 minute", function () {
  assert.deepEqual(code.windowOverlap({ start: "09:00", end: "12:01" }, { start: "12:00", end: "13:00" }), { overlaps: true, minutes: 1 });
});

test("one minute short of a shared endpoint does not overlap", function () {
  assert.deepEqual(code.windowOverlap({ start: "09:00", end: "11:59" }, { start: "12:00", end: "13:00" }), { overlaps: false, minutes: 0 });
});

test("windows separated by a gap do not overlap", function () {
  assert.deepEqual(code.windowOverlap({ start: "08:10", end: "09:40" }, { start: "11:05", end: "12:20" }), { overlaps: false, minutes: 0 });
});

test("a gap still does not overlap when the later window is given first", function () {
  assert.deepEqual(code.windowOverlap({ start: "11:05", end: "12:20" }, { start: "08:10", end: "09:40" }), { overlaps: false, minutes: 0 });
});

test("an inner window overlaps by 90 minutes not the outer length", function () {
  assert.deepEqual(code.windowOverlap({ start: "09:00", end: "12:00" }, { start: "10:00", end: "11:30" }), { overlaps: true, minutes: 90 });
});

test("an inner window given first still overlaps by 90 minutes", function () {
  assert.deepEqual(code.windowOverlap({ start: "10:00", end: "11:30" }, { start: "09:00", end: "12:00" }), { overlaps: true, minutes: 90 });
});

test("a shared endpoint does not overlap when the later window is given first", function () {
  assert.deepEqual(code.windowOverlap({ start: "12:00", end: "13:00" }, { start: "09:00", end: "12:00" }), { overlaps: false, minutes: 0 });
});

test("the smallest positive overlap is 1 minute not the outer length", function () {
  assert.deepEqual(code.windowOverlap({ start: "13:00", end: "15:00" }, { start: "14:00", end: "14:01" }), { overlaps: true, minutes: 1 });
});

test("overlap at the start of the day is 15 minutes", function () {
  assert.deepEqual(code.windowOverlap({ start: "00:00", end: "00:40" }, { start: "00:25", end: "01:10" }), { overlaps: true, minutes: 15 });
});

test("overlap near the end of the day is 10 minutes", function () {
  assert.deepEqual(code.windowOverlap({ start: "22:10", end: "23:50" }, { start: "23:40", end: "23:59" }), { overlaps: true, minutes: 10 });
});

test("overlap near the end of the day is 10 minutes when reversed", function () {
  assert.deepEqual(code.windowOverlap({ start: "23:40", end: "23:59" }, { start: "22:10", end: "23:50" }), { overlaps: true, minutes: 10 });
});

test("an unknown field on the first window throws unknown field driver", function () {
  assert.throws(function () {
    code.windowOverlap({ start: "09:00", end: "11:00", driver: "A" }, { start: "10:30", end: "12:00" });
  }, /^unknown field: driver$/);
});

test("an unknown field on the second window throws unknown field priority", function () {
  assert.throws(function () {
    code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00", priority: "high" });
  }, /^unknown field: priority$/);
});
